input.command:
for i in 0 1 2 3; do echo "== iter $i"; python3 -c "
import json;d=json.load(open('iter_$i/critique/ppc_results.json'))
r=d['results'] if isinstance(d,dict) and 'results' in d else d
for x in (r if isinstance(r,list) else [dict(name=k,**v) for k,v in r.items()]):
    print(x.get('name'), round(x.get('t_observed',0),3), round(x.get('null_mean',0),3), round(x.get('p_value',1),3))
"; done

